func TestASourceBitsetHasOneClass(emonT *testing.T) {
	port.AssertEq(emonT, calib.CalClass(model.SrText()), 0, "text layer")
	port.AssertEq(emonT, calib.CalClass(model.SrHiddenText()), 0, "hidden text is the text layer's")
	port.AssertEq(emonT, calib.CalClass(model.SrText()|model.SrInfer()), 0, "text and inferred structure: the text layer's")
	port.AssertEq(emonT, calib.CalClass(model.SrOcr()), 1, "OCR")
	port.AssertEq(emonT, calib.CalClass(model.SrOcr()|model.SrInfer()), 1, "OCR and inferred structure: OCR's")
	port.AssertEq(emonT, calib.CalClass(model.SrText()|model.SrOcr()), 2, "both")
	port.AssertEq(emonT, calib.CalClass(model.SrHiddenText()|model.SrOcr()), 2, "hidden text and OCR: both")
	port.AssertEq(emonT, calib.CalClass(model.SrInfer()), 3, "inferred only")
	port.AssertEq(emonT, calib.CalClass(model.SrStruct()), 3, "the tagged tree only: neither")
	port.AssertEq(emonT, calib.CalClass(0), 3, "no source")
}

func TestTheLedgerHasAKindCodeNoNodeKindHas(emonT *testing.T) {
	port.AssertEq(emonT, calib.CalDropped(), 100, "the dropped ledger")
	port.AssertThat(emonT, calib.CalDropped() > 26, "above the last node kind")
}

func TestAnAbsentConfidenceStaysAbsent(emonT *testing.T) {
	port.AssertEq(emonT, calib.CalConf(model.NkParagraph(), model.SrText(), -1), -1, "paragraph")
	port.AssertEq(emonT, calib.CalConf(calib.CalDropped(), model.SrOcr(), -1), -1, "dropped")
}

func TestAKindWithNoRowGoesThroughAsItIs(emonT *testing.T) {
	// Kind 99 is no node kind and no ledger code: no fit has a row for it.
	port.AssertEq(emonT, calib.CalConf(99, model.SrText(), 123), 123, "123")
	port.AssertEq(emonT, calib.CalConf(99, model.SrOcr(), 0), 0, "0")
	port.AssertEq(emonT, calib.CalConf(99, 0, 1000), 1000, "1000")
}

func TestTheTableIsSortedAndMonotoneInTheRawScore(emonT *testing.T) {
	// Rows are [kind class raw-lo calibrated], sorted by kind, class, raw-lo; within one kind and class the raw-lo rises strictly
	// and the calibrated value never falls (isotonic), and a value is a confidence.
	var n int32 = 30
	var i int32 = 1
	port.AssertThat(emonT, n > 0, "the table has a row (the identity table has one that no node matches)")
	for i < n {
		var k0 int32 = calibdata.CdRows[(i-1)*4+0]
		var c0 int32 = calibdata.CdRows[(i-1)*4+1]
		var k1 int32 = calibdata.CdRows[i*4+0]
		var c1 int32 = calibdata.CdRows[i*4+1]
		port.AssertThat(emonT, (k0 < k1) || ((k0 == k1) && (c0 <= c1)), "sorted by kind then class")
		if (k0 == k1) && (c0 == c1) {
			port.AssertThat(emonT, calibdata.CdRows[(i-1)*4+2] < calibdata.CdRows[i*4+2], "raw-lo rises within a kind and class")
			port.AssertThat(emonT, calibdata.CdRows[(i-1)*4+3] <= calibdata.CdRows[i*4+3], "calibrated never falls with the raw score")
		}
		port.AssertThat(emonT, (calibdata.CdRows[i*4+3] >= 0) && (calibdata.CdRows[i*4+3] <= 1000), "a calibrated value is 0..1000")
		i += 1
	}
}

func TestEveryStepOfTheTableAnswersWithItsOwnValue(emonT *testing.T) {
	// At a step's raw-lo (and one above it, if that is still below the next step) the lookup is the step's value,
	// for the class the row names (an `any` row is read through a class that has no row of its own: a class code
	// the table never names, 9, falls back to `any`).
	var n int32 = 30
	var i int32 = 0
	for i < n {
		if calibdata.CdRows[i*4+1] == -1 {
			port.AssertEqAt(emonT, calib.CalLookup(calibdata.CdRows[i*4+0], 9, calibdata.CdRows[i*4+2]), calibdata.CdRows[i*4+3], "an any-row at its raw-lo", i)
		}
		i += 1
	}
}

func TestTheLookupClampsAtBothEndsOfAStepFunction(emonT *testing.T) {
	// Below a row's first step the first step's value; above the last the last's (no extrapolation).
	var n int32 = 30
	var i int32 = 0
	for i < n {
		if calibdata.CdRows[i*4+1] == -1 {
			var kind int32 = calibdata.CdRows[i*4+0]
			var firstV int32 = -1
			var lastV int32 = -1
			var j int32 = 0
			for j < n {
				if (calibdata.CdRows[j*4+0] == kind) && (calibdata.CdRows[j*4+1] == -1) {
					if firstV < 0 {
						firstV = calibdata.CdRows[j*4+3]
					}
					lastV = calibdata.CdRows[j*4+3]
				}
				j += 1
			}
			port.AssertEqAt(emonT, calib.CalLookup(kind, 9, 0), firstV, "raw 0 takes the first step", i)
			port.AssertEqAt(emonT, calib.CalLookup(kind, 9, 1000), lastV, "raw 1000 takes the last step", i)
		}
		i += 1
	}
}

func TestABlockFlaggedScriptUnreadIsWrittenAtItsRawScore(emonT *testing.T) {
	// D564: the map clamps at its first step, so a raw 100 on OCR text is written as the lowest confidence of text the engine READ; the engine's guess at a script it
	// cannot read keeps its raw score, and so do the inlines under it
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	var p1 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var t1 int32 = model.NodeNew(nodes, model.NkText(), p1)
	var p2 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	model.NodeAddSrc(nodes, p1, model.SrOcr())
	model.NodeSetConf(nodes, p1, 100)
	model.NodeAddFlag(nodes, p1, model.FlScriptUnread())
	model.NodeAddSrc(nodes, t1, model.SrOcr())
	model.NodeSetConf(nodes, t1, 100)
	model.NodeAddSrc(nodes, p2, model.SrOcr())
	model.NodeSetConf(nodes, p2, 100)
	var mapped int32 = calib.CalConf(model.NkParagraph(), model.SrOcr(), 100)
	var want int32 = 100
	if mapped < 100 {
		want = mapped
	}
	port.AssertEq(emonT, calib.CalNodeConf(nodes, p1), want, "the flagged block: its raw score, when the map would give more")
	port.AssertThat(emonT, calib.CalNodeConf(nodes, p1) <= 100, "never above it")
	port.AssertThat(emonT, calib.CalNodeConf(nodes, t1) <= 100, "the text under it too")
	port.AssertEq(emonT, calib.CalNodeConf(nodes, p2), mapped, "a block no one flagged is calibrated as it was")
}
